// The GEO interface of the engine (it came from mrdoob/slop-newyork), backed by Geneva's city centre.
// The New York-specific entries are empty; the mapped city lives in GEO.geneva (the irregular-city data path of the
// engine, see geneva-geometry.js) and is generated by tools/build-geneva-geodata.mjs.
import { GENEVA_DATA } from './geneva-geodata.js';

const [minX, minZ, maxX, maxZ] = GENEVA_DATA.meta.bounds;

export const GEO = {
  version: 2,
  city: 'Genève',
  cityName: 'Genève',
  irregular: true,
  frame: { bearingDeg: 0, origin: 'Rhône · Bel-Air (LV95 2500000 / 1118000)', units: 'm', cutZ: minZ, strip: 20, sidewalk: 3 },
  outline: [minX, minZ, maxX, minZ, maxX, maxZ, minX, maxZ], // the mapped city's outline
  upperManhattan: [],
  streets: [],
  avenues: [],
  broadway: [],
  piers: [],
  islands: {},
  boroughs: { newJersey: [], brooklyn: [], queens: [], bronx: [], statenIsland: [] },
  bridges: {},
  points: {},
  plazas: [],
  centralPark: { bounds: { minX, maxX, minZ, maxZ }, lawns: [], water: GENEVA_DATA.water, drives: [] },
  parks: GENEVA_DATA.parks.map((p) => ({ name: p.name, kind: p.kind, rings: [p.ring], holes: p.holes })),
  landmarks: GENEVA_DATA.landmarks,
  roads: [],
  blocks: [],
  roadGraph: GENEVA_DATA.roadGraph,
  geneva: GENEVA_DATA
};
